package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's locality (region) from its city using a fixed city-to-region table
 * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). Any city not listed yields "UNKNOWN".
 */
public final class Locality {

    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    private Locality() {
    }

    public static String of(Owner owner) {
        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;

/**
 * Rejects a create when the owner's city already holds {@value #CAPACITY} or more owners
 * (compared case-insensitively with collapsed whitespace).
 */
public class EnsureOwnerCityWithinCapacity {

    private static final int CAPACITY = 50;

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = key(owner.getCity());
        long count = ownerRepository.findAll().stream()
                .filter(other -> key(other.getCity()).equals(city))
                .count();
        if (count >= CAPACITY) {
            throw new CityAtCapacityException("This city already has the maximum number of owners");
        }
    }

    private static String key(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

import org.springframework.samples.petclinic.rest.escalation.AddressRequiredException;

/**
 * Normalises a postal address: trim and collapse runs of whitespace to single spaces,
 * upper-case, and expand common abbreviations token by token (ST->STREET, RD->ROAD,
 * AVE->AVENUE). A value that is blank once whitespace is collapsed is rejected, so the
 * required-field check applies to the normalised form.
 */
final class Address {

    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");

    private Address() {
    }

    static String normalize(String address) throws AddressRequiredException {
        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
        if (collapsed.isEmpty()) {
            throw new AddressRequiredException("Address is required");
        }
        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
        }
        return sb.toString();
    }
}

